parameters.jsCode:
const body = $input.first().json.body;
const required = ['title', 'description', 'reporter'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}
if (body.description.trim().length < 20) {
  return [{ json: { valid: false, error: 'description too short — explain what happened' } }];
}
const severities = ['critical', 'high', 'medium', 'low'];
const reportedSeverity = severities.includes(body.reported_severity) ? body.reported_severity : null;
return [{
  json: {
    valid: true,
    bugId: `BUG-${Date.now()}`,
    title: body.title.trim(),
    description: body.description.trim().slice(0, 2000),
    stepsToReproduce: (body.steps_to_reproduce || '').slice(0, 1000),
    expectedBehavior: body.expected_behavior || '',
    actualBehavior: body.actual_behavior || '',
    reporter: body.reporter.trim(),
    reporterEmail: body.reporter_email || null,
    affectedComponent: body.affected_component || '',
    affectedUsers: body.affected_users || '',
    environment: body.environment || 'production',
    reportedSeverity,
    browserOrPlatform: body.browser_or_platform || '',
    errorMessage: (body.error_message || '').slice(0, 500),
    notifySlack: body.notify_slack_channel || null,
    reportedAt: new Date().toISOString()
  }
}];

