const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let triage;
try {
  triage = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse error', raw } }];
}
const bug = $('Validate Bug Report').first().json;
triage._bug = bug;
return [{ json: triage }];

