parameters.jsCode:
const bugs = $input.all().map(r => r.json).filter(b => b.bug_id && b.status !== 'closed');
const bySeverity = { critical: [], high: [], medium: [], low: [] };
for (const b of bugs) {
  const sev = b.severity || 'low';
  if (bySeverity[sev]) bySeverity[sev].push(b);
}
const now = new Date();
const stale = bugs.filter(b => {
  const age = Math.floor((now - new Date(b.reported_at)) / 86400000);
  return age >= 3 && b.severity === 'critical' || age >= 7 && b.severity === 'high' || age >= 14 && b.severity === 'medium';
});
return [{ json: { bugs, bySeverity, stale, totalOpen: bugs.length, reportDate: now.toISOString().split('T')[0] } }];

