const note = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
const d = $('Analyse Bug Queue').first().json;
function esc(s) { return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
const sevColor = { critical: '#dc2626', high: '#d97706', medium: '#2563eb', low: '#6b7280' };
const bugRows = d.bugs.slice(0, 20).map(b => `<tr style="border-bottom:1px solid #f3f4f6"><td style="padding:8px 12px;font-family:monospace;font-size:12px">${esc(b.bug_id)}</td><td style="padding:8px 12px;font-size:13px">${esc(b.title)}</td><td style="padding:8px 12px"><span style="background:${sevColor[b.severity]||'#6b7280'}22;color:${sevColor[b.severity]||'#6b7280'};font-size:11px;font-weight:700;padding:2px 7px;border-radius:8px">${esc(b.severity||'?')}</span></td><td style="padding:8px 12px;font-size:13px;color:#6b7280">${esc(b.bug_type||'')}</td><td style="padding:8px 12px;font-size:13px;color:#6b7280">${esc(b.suggested_owner||'')}</td></tr>`).join('');
const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="margin:0;padding:16px;background:#f9fafb;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;color:#111">
<div style="max-width:660px;margin:0 auto">
  <div style="background:#111827;color:#fff;padding:18px 26px;border-radius:10px 10px 0 0">
    <div style="font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6b7280;margin-bottom:4px">Daily Bug Digest · ${esc(d.reportDate)}</div>
    <div style="font-size:18px;font-weight:700">${d.totalOpen} open bugs · ${d.bySeverity.critical.length} critical · ${d.stale.length} stale</div>
  </div>
  <div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:none">
    <p style="font-size:14px;line-height:1.7;color:#374151;margin:0">${esc(note).replace(/\n/g,'<br>')}</p>
  </div>
  <div style="background:#fff;padding:16px 26px;border:1px solid #e5e7eb;border-top:3px solid #f3f4f6">
    <table style="width:100%;border-collapse:collapse"><thead><tr style="font-size:11px;text-transform:uppercase;color:#9ca3af"><th style="padding:6px 12px;text-align:left">ID</th><th style="padding:6px 12px;text-align:left">Title</th><th style="padding:6px 12px;text-align:left">Severity</th><th style="padding:6px 12px;text-align:left">Type</th><th style="padding:6px 12px;text-align:left">Owner</th></tr></thead><tbody>${bugRows}</tbody></table>
  </div>
  <div style="background:#111827;color:#4b5563;font-size:11px;padding:10px 26px;border-radius:0 0 10px 10px;font-family:monospace;text-align:center">Bug Triage Agent · ${esc(d.reportDate)}</div>
</div></body></html>`;
return [{ json: { html, totalOpen: d.totalOpen, criticalCount: d.bySeverity.critical.length } }];
